import{_ as t,o as s,c as a,ah as n}from"./chunks/framework.BsNNkeaH.js";const f=JSON.parse('{"title":"Transferts de site","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/secretariat/transferts-sites.md","filePath":"src/guide/secretariat/transferts-sites.md"}'),r={name:"guide/secretariat/transferts-sites.md"};function i(o,e,l,u,d,p){return s(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="transferts-de-site" tabindex="-1">Transferts de site <a class="header-anchor" href="#transferts-de-site" aria-label="Permalink to &quot;Transferts de site&quot;">​</a></h1><p>Un parent peut demander, depuis son espace, à transférer son enfant d&#39;un site de l&#39;établissement vers un autre (par exemple d&#39;un campus à un autre). La page <strong>Mobilité inter-site</strong> liste ces demandes et vous permet de les faire aboutir. Une demande doit être approuvée à la fois par le site d&#39;origine et par le site de destination avant que le transfert ne soit effectif — vous jouez ce rôle des deux côtés.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Cette page concerne uniquement les transferts d&#39;<strong>élèves</strong> entre deux sites. Les transferts de personnel entre sites sont une fonctionnalité distincte, réservée à l&#39;administration.</p></div><h2 id="consulter-la-file-d-attente" tabindex="-1">Consulter la file d&#39;attente <a class="header-anchor" href="#consulter-la-file-d-attente" aria-label="Permalink to &quot;Consulter la file d&#39;attente&quot;">​</a></h2><p>La page affiche pour chaque demande l&#39;élève concerné, le site d&#39;origine, le site de destination et le statut (<strong>En attente</strong>, <strong>Approuvé</strong> ou <strong>Refusé</strong>). Utilisez le filtre de statut pour ne voir que les demandes qui vous intéressent, puis cliquez sur <strong>Examiner</strong> pour ouvrir une demande.</p><h2 id="examiner-une-demande" tabindex="-1">Examiner une demande <a class="header-anchor" href="#examiner-une-demande" aria-label="Permalink to &quot;Examiner une demande&quot;">​</a></h2><p>La page de détail affiche qui a <strong>demandé</strong> le transfert, le <strong>site d&#39;origine</strong>, le <strong>site de destination</strong>, le <strong>département</strong> souhaité sur le nouveau site et, si elle a été renseignée, le <strong>motif</strong> de la demande.</p><h2 id="approuver-un-transfert" tabindex="-1">Approuver un transfert <a class="header-anchor" href="#approuver-un-transfert" aria-label="Permalink to &quot;Approuver un transfert&quot;">​</a></h2><p>Le formulaire présente deux blocs distincts, l&#39;un pour chaque site concerné :</p><ol><li>Dans <strong>Validation du site d&#39;origine</strong>, cliquez sur <strong>Approuver l&#39;origine</strong>. Si ce bloc affiche déjà le nom d&#39;une personne, ce site a déjà donné son accord et vous n&#39;avez rien à faire ici.</li><li>Dans <strong>Validation du site de destination</strong>, choisissez la <strong>classe</strong> d&#39;accueil sur le nouveau site (l&#39;occupation de chaque classe est indiquée, par exemple <code>18/25</code>). Si la classe a atteint sa capacité, cochez <strong>Forcer l&#39;affectation même si la classe a atteint sa capacité</strong> pour l&#39;assigner malgré tout, puis cliquez sur <strong>Approuver la destination</strong>.</li></ol><p>Dès que les deux sites ont donné leur accord — peu importe l&#39;ordre — le transfert est exécuté automatiquement : l&#39;élève est déplacé vers le nouveau site, département et classe, sans action supplémentaire de votre part.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Une version simplifiée de cette page, sans menu ni navigation, peut s&#39;ouvrir directement depuis un lien reçu par notification (par exemple sur votre téléphone) : elle permet d&#39;approuver l&#39;origine, la destination, ou de refuser la demande, sans avoir à naviguer dans le reste de l&#39;appli.</p></div><h2 id="refuser-une-demande" tabindex="-1">Refuser une demande <a class="header-anchor" href="#refuser-une-demande" aria-label="Permalink to &quot;Refuser une demande&quot;">​</a></h2><ol><li>Depuis la page de détail d&#39;une demande en attente, cliquez sur <strong>Refuser</strong>.</li><li>Indiquez le <strong>Motif de refus</strong> (obligatoire).</li><li>Confirmez en cliquant à nouveau sur <strong>Refuser</strong>.</li></ol><p>Une demande refusée ne peut plus être approuvée : la famille doit en soumettre une nouvelle si elle souhaite réessayer.</p>',15)])])}const m=t(r,[["render",i]]);export{f as __pageData,m as default};
